cat > output/styles.css <<'EOF'
:root{
  --bg:#ffffff;
  --surface:#f5f5f7;
  --surface-2:#efeff2;
  --text:#1d1d1f;
  --muted:#6e6e73;
  --line:rgba(0,0,0,.08);
  --accent:#0066cc;
  --accent-2:#0a84ff;
  --radius:22px;
  --shadow:0 18px 50px rgba(0,0,0,.10);
  --shadow-soft:0 10px 30px rgba(0,0,0,.08);
  --max:1200px;
  --gutter:24px;
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, "Apple Color Emoji", "Segoe UI Emoji";
  color:var(--text);
  background: radial-gradient(1200px 600px at 20% -10%, rgba(0,102,204,.08), transparent 60%),
              radial-gradient(900px 500px at 95% 10%, rgba(255,140,0,.06), transparent 55%),
              var(--bg);
}
img{max-width:100%; display:block}

a{color:var(--accent); text-decoration:none}
a:hover{text-decoration:underline}

.container{max-width:var(--max); margin:0 auto; padding:0 var(--gutter)}

.topbar{
  position:sticky; top:0; z-index:50;
  backdrop-filter:saturate(180%) blur(18px);
  background:rgba(245,245,247,.72);
  border-bottom:1px solid var(--line);
}
.nav{
  height:52px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:16px;
}
.brand{
  display:flex; align-items:center; gap:10px;
  font-weight:650; letter-spacing:.1px;
}
.logo{
  width:22px; height:22px; border-radius:7px;
  background: linear-gradient(135deg, rgba(0,102,204,.95), rgba(10,132,255,.25));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.6);
}
.navlinks{display:flex; align-items:center; gap:16px; flex-wrap:wrap}
.navlinks a{color:var(--text); font-size:13px; opacity:.86}
.navlinks a:hover{opacity:1; text-decoration:none}
.navlinks a.active{opacity:1}

.ribbon{
  background:linear-gradient(90deg, rgba(0,102,204,.12), rgba(0,102,204,.06));
  border-bottom:1px solid var(--line);
}
.ribbon .container{
  padding:10px var(--gutter);
  font-size:13px;
  color:var(--text);
}
.ribbon a{font-weight:600}

.hero{
  padding:42px 0 24px;
}
.hero-grid{
  display:grid;
  grid-template-columns: 1.1fr .9fr;
  gap:26px;
  align-items:stretch;
}
.hero-card{
  border-radius:var(--radius);
  background:linear-gradient(180deg, rgba(255,255,255,.88), rgba(245,245,247,.88));
  border:1px solid var(--line);
  box-shadow:var(--shadow-soft);
  overflow:hidden;
  position:relative;
}
.hero-card::before{
  content:"";
  position:absolute; inset:-60px;
  background: radial-gradient(600px 260px at 20% 20%, rgba(10,132,255,.25), transparent 60%),
              radial-gradient(520px 260px at 70% 50%, rgba(255,170,40,.16), transparent 60%);
  transform: rotate(-6deg);
  opacity:.75;
}
.hero-inner{position:relative; padding:28px}
.kicker{display:inline-flex; align-items:center; gap:8px; font-size:12px; color:var(--muted)}
.dot{width:6px; height:6px; border-radius:999px; background:var(--accent)}
.h1{font-size:52px; line-height:1.02; letter-spacing:-.04em; margin:12px 0 8px; font-weight:720}
.sub{font-size:16px; color:var(--muted); max-width:52ch; line-height:1.55}
.cta-row{display:flex; gap:12px; flex-wrap:wrap; margin-top:18px}

.btn{
  display:inline-flex; align-items:center; justify-content:center;
  gap:8px;
  padding:10px 14px;
  border-radius:999px;
  font-size:13px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.78);
  color:var(--text);
  text-decoration:none;
  cursor:pointer;
}
.btn:hover{box-shadow:0 10px 22px rgba(0,0,0,.10); text-decoration:none}
.btn.primary{
  background:var(--accent);
  border-color: rgba(0,0,0,.06);
  color:white;
}
.btn.primary:hover{background:var(--accent-2)}
.btn.ghost{background:transparent}

.hero-mini{
  padding:22px;
  display:flex; flex-direction:column; gap:14px;
}
.mini-title{font-size:13px; color:var(--muted)}
.mini-block{
  border-radius:18px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.7);
  padding:14px;
}
.mini-block strong{font-size:14px}
.mini-block span{display:block; color:var(--muted); font-size:13px; margin-top:6px; line-height:1.45}

.section{padding:36px 0}
.section-head{display:flex; align-items:flex-end; justify-content:space-between; gap:16px; margin-bottom:14px}
.section-title{font-size:34px; letter-spacing:-.03em; margin:0; font-weight:720}
.section-sub{margin:0; color:var(--muted); font-size:14px; line-height:1.5; max-width:70ch}

.grid-tiles{
  display:grid;
  grid-template-columns: repeat(12, 1fr);
  gap:18px;
}
.tile{
  grid-column: span 6;
  border-radius:28px;
  border:1px solid var(--line);
  background:linear-gradient(180deg, rgba(245,245,247,.88), rgba(255,255,255,.88));
  box-shadow:var(--shadow-soft);
  overflow:hidden;
  position:relative;
  min-height:320px;
}
.tile.big{grid-column: span 12; min-height:420px}
.tile.cool{background: radial-gradient(700px 400px at 25% 15%, rgba(10,132,255,.20), transparent 55%),
                    linear-gradient(180deg, rgba(245,245,247,.9), rgba(255,255,255,.9))}
.tile.warm{background: radial-gradient(700px 400px at 20% 25%, rgba(255,170,40,.18), transparent 55%),
                    linear-gradient(180deg, rgba(245,245,247,.9), rgba(255,255,255,.9))}
.tile.neutral{background: linear-gradient(180deg, rgba(245,245,247,.92), rgba(255,255,255,.92))}

.tile-inner{position:relative; padding:28px}
.tile h3{font-size:40px; letter-spacing:-.04em; margin:0 0 8px; font-weight:740}
.tile p{margin:0; color:var(--muted); font-size:15px; line-height:1.5; max-width:55ch}
.tile .cta-row{margin-top:14px}

.product-visual{
  position:absolute; right:18px; bottom:-20px;
  width:min(360px, 52%);
  aspect-ratio: 4 / 3;
  border-radius:26px;
  background: linear-gradient(135deg, rgba(0,0,0,.06), rgba(0,0,0,.02));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.6);
  overflow:hidden;
}
.product-visual::before{
  content:"";
  position:absolute; inset:-40px;
  background:
    radial-gradient(220px 140px at 30% 30%, rgba(255,255,255,.8), transparent 60%),
    radial-gradient(240px 180px at 65% 50%, rgba(10,132,255,.25), transparent 60%),
    radial-gradient(260px 180px at 60% 90%, rgba(255,170,40,.18), transparent 60%);
  transform: rotate(8deg);
  opacity:.95;
}
.product-visual .lines{position:absolute; inset:0; opacity:.26; mix-blend-mode:multiply}

.card-row{
  display:flex; gap:14px; align-items:stretch;
}

.carousel{
  position:relative;
}
.carousel-track{
  display:flex;
  gap:14px;
  overflow-x:auto;
  scroll-snap-type:x mandatory;
  scroll-behavior:smooth;
  padding:4px 2px 10px;
  scrollbar-width:none;
}
.carousel-track::-webkit-scrollbar{display:none}

.carousel-card{
  scroll-snap-align:start;
  flex: 0 0 320px;
  border-radius:24px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.78);
  box-shadow:var(--shadow-soft);
  overflow:hidden;
}
.carousel-card .cinner{padding:18px}
.badge{
  display:inline-flex; align-items:center; gap:8px;
  padding:4px 10px;
  border-radius:999px;
  font-size:11px;
  background:rgba(0,102,204,.12);
  color:var(--accent);
  font-weight:700;
  letter-spacing:.06em;
}
.c-title{font-size:18px; margin:10px 0 6px; font-weight:720; letter-spacing:-.02em}
.c-sub{color:var(--muted); font-size:13px; line-height:1.45; margin:0 0 10px; min-height:38px}
.price{font-size:13px; color:var(--text); font-weight:650}
.monthly{font-size:12px; color:var(--muted); margin-top:4px}

.nav-arrows{
  position:absolute;
  inset:0;
  pointer-events:none;
}
.arrow{
  pointer-events:auto;
  position:absolute;
  top:50%;
  transform: translateY(-50%);
  width:44px; height:44px;
  border-radius:999px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.82);
  backdrop-filter: blur(10px);
  box-shadow: 0 12px 28px rgba(0,0,0,.12);
  display:grid; place-items:center;
  cursor:pointer;
}
.arrow:hover{background:white}
.arrow.left{left:-10px}
.arrow.right{right:-10px}
.arrow svg{width:18px; height:18px}

.iconbar{
  display:flex; gap:14px;
  overflow-x:auto;
  padding:10px 2px;
  scrollbar-width:none;
}
.iconbar::-webkit-scrollbar{display:none}
.icon-pill{
  flex:0 0 auto;
  display:flex; flex-direction:column; align-items:center;
  gap:10px;
  padding:10px 12px;
  border-radius:18px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.74);
  min-width:92px;
}
.icon{
  width:46px; height:46px; border-radius:18px;
  background: radial-gradient(26px 26px at 30% 30%, rgba(255,255,255,.9), rgba(0,0,0,.06));
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.7);
}
.icon-pill span{font-size:12px; color:var(--text); opacity:.9}
.icon-pill:hover{box-shadow:0 12px 26px rgba(0,0,0,.10)}

.tabs{
  border-radius:28px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.76);
  box-shadow: var(--shadow-soft);
  overflow:hidden;
}
.tablist{
  display:flex;
  gap:6px;
  padding:10px;
  border-bottom:1px solid var(--line);
  background: linear-gradient(180deg, rgba(245,245,247,.92), rgba(255,255,255,.76));
}
.tabbtn{
  flex:1;
  padding:10px 12px;
  border-radius:999px;
  border:1px solid transparent;
  background:transparent;
  cursor:pointer;
  font-size:13px;
  color:var(--muted);
}
.tabbtn[aria-selected="true"]{
  background:white;
  border-color: var(--line);
  color: var(--text);
  box-shadow: 0 12px 28px rgba(0,0,0,.08);
}
.tabpanel{display:none; padding:14px}
.tabpanel.active{display:block}

.sticky-subnav{
  position:sticky;
  top:52px;
  z-index:40;
  background: rgba(245,245,247,.76);
  backdrop-filter:saturate(180%) blur(18px);
  border-bottom:1px solid var(--line);
}
.subnav{
  display:flex;
  gap:10px;
  overflow-x:auto;
  padding:10px var(--gutter);
  scrollbar-width:none;
}
.subnav::-webkit-scrollbar{display:none}
.subnav a{
  flex:0 0 auto;
  padding:8px 12px;
  border-radius:999px;
  color:var(--text);
  font-size:13px;
  opacity:.78;
  border:1px solid transparent;
}
.subnav a:hover{opacity:1; text-decoration:none}
.subnav a.current{
  opacity:1;
  background:white;
  border-color: var(--line);
  box-shadow:0 12px 26px rgba(0,0,0,.08);
}

.info-grid{
  display:grid;
  grid-template-columns: repeat(12,1fr);
  gap:16px;
}
.info-card{
  grid-column: span 4;
  border-radius:24px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.78);
  box-shadow: var(--shadow-soft);
  padding:18px;
}
.info-card h4{margin:0 0 8px; font-size:16px; letter-spacing:-.02em}
.info-card p{margin:0; color:var(--muted); font-size:13px; line-height:1.55}

.quicklinks{display:flex; flex-wrap:wrap; gap:10px}
.quicklinks a{
  border:1px solid var(--line);
  background: rgba(255,255,255,.78);
  border-radius:999px;
  padding:10px 12px;
  color:var(--text);
  font-size:13px;
}
.quicklinks a:hover{text-decoration:none; box-shadow:0 12px 26px rgba(0,0,0,.09)}

.footer{
  margin-top:30px;
  border-top:1px solid var(--line);
  background: rgba(245,245,247,.72);
  backdrop-filter:saturate(180%) blur(18px);
}
.footer-inner{padding:26px 0}
.footer-grid{display:grid; grid-template-columns: repeat(12,1fr); gap:16px}
.footer-col{grid-column: span 3}
.footer h5{margin:0 0 10px; font-size:12px; color:var(--text); letter-spacing:.06em; text-transform:uppercase}
.footer a{display:block; padding:6px 0; color:var(--muted); font-size:13px}
.footer a:hover{color:var(--text); text-decoration:none}
.legal{color:var(--muted); font-size:12px; line-height:1.55; padding:16px 0 26px}

/* Mobile footer accordion */
.footer-accordion{display:none}
.accordion-item{border-top:1px solid var(--line)}
.accordion-btn{
  width:100%;
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:14px 0;
  background:transparent;
  border:none;
  font-size:12px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--text);
  cursor:pointer;
}
.accordion-panel{display:none; padding:0 0 12px}
.accordion-panel a{padding:6px 0}
.accordion-item.open .accordion-panel{display:block}

@media (max-width: 980px){
  .hero-grid{grid-template-columns: 1fr}
  .tile h3{font-size:34px}
  .h1{font-size:44px}
  .product-visual{width:58%}
  .info-card{grid-column: span 6}
  .footer-col{grid-column: span 4}
}
@media (max-width: 768px){
  :root{--gutter:18px}
  .h1{font-size:36px}
  .section-title{font-size:26px}
  .tile{grid-column: span 12; min-height:340px}
  .tile.big{min-height:360px}
  .product-visual{position:relative; right:auto; bottom:auto; margin-top:16px; width:100%}
  .arrow.left{left:4px}
  .arrow.right{right:4px}
  .footer-grid{display:none}
  .footer-accordion{display:block}
}
EOF

