.subnav a{
  flex:0 0 auto;
  padding:8px 12px;
  border-radius:999px;
  color:var(--text);
  font-size:13px;
  opacity:.78;
  border:1px solid transparent;
}
.subnav a:hover{opacity:1; text-decoration:none}
.subnav a.current{
  opacity:1;
  background:white;
  border-color: var(--line);
  box-shadow:0 12px 26px rgba(0,0,0,.08);
}

.info-grid{
  display:grid;
  grid-template-columns: repeat(12,1fr);
  gap:16px;
