.info-card{
  grid-column: span 4;
  border-radius:24px;
  border:1px solid var(--line);
  background: rgba(255,255,255,.78);
  box-shadow: var(--shadow-soft);
  padding:18px;
}
.info-card h4{margin:0 0 8px; font-size:16px; letter-spacing:-.02em}
.info-card p{margin:0; color:var(--muted); font-size:13px; line-height:1.55}

.quicklinks{display:flex; flex-wrap:wrap; gap:10px}
.quicklinks a{
  border:1px solid var(--line);
  background: rgba(255,255,255,.78);
  border-radius:999px;
  padding:10px 12px;
  color:var(--text);
  font-size:13px;
}
.quicklinks a:hover{text-decoration:none; box-shadow:0 12px 26px rgba(0,0,0,.09)}

.footer{
  margin-top:30px;
  border-top:1px solid var(--line);
  background: rgba(245,245,247,.72);
  backdrop-filter:saturate(180%) blur(18px);
}
.footer-inner{padding:26px 0}
.footer-grid{display:grid; grid-template-columns: repeat(12,1fr); gap:16px}
.footer-col{grid-column: span 3}
.footer h5{margin:0 0 10px; font-size:12px; color:var(--text); letter-spacing:.06em; text-transform:uppercase}
.footer a{display:block; padding:6px 0; color:var(--muted); font-size:13px}
.footer a:hover{color:var(--text); text-decoration:none}
.legal{color:var(--muted); font-size:12px; line-height:1.55; padding:16px 0 26px}

/* Mobile footer accordion */
.footer-accordion{display:none}
.accordion-item{border-top:1px solid var(--line)}
.accordion-btn{
  width:100%;
  display:flex;
  justify-content:space-between;
  align-items:center;
  padding:14px 0;
  background:transparent;
  border:none;
  font-size:12px;
  letter-spacing:.06em;
  text-transform:uppercase;
  color:var(--text);
